const modelGuide = 'https://support.apple.com/en-us/108044';
const records = [
[2007,'iPhone','Hello, iPhone.','A phone, a music player, and the internet, brought together on one Multi-Touch screen. The original iPhone replaced a crowded keypad with a remarkably simple idea: just touch.',['Multi-Touch','Safari','iPod built in'],'3.5 inches','Samsung ARM','June 29, 2007','https://www.apple.com/newsroom/2007/01/09Apple-Reinvents-the-Phone-with-iPhone/'],
[2008,'iPhone 3G','A phone becomes a platform.','Faster cellular data and built-in GPS made the iPhone more useful on the move. Alongside iPhone 3G, the App Store opened a new chapter for independent developers and mobile software.',['3G connectivity','App Store','GPS'],'3.5 inches','Samsung ARM','July 11, 2008','https://www.apple.com/newsroom/2008/06/09Apple-Introduces-the-New-iPhone-3G/'],
[2009,'iPhone 3GS','The S stood for speed.','The familiar shape returned with faster performance, video recording, and Voice Control. A built-in compass added a new sense of direction to mobile navigation.',['Video recording','Voice Control','Compass'],'3.5 inches','Samsung ARM','June 19, 2009',modelGuide],
[2010,'iPhone 4','Everything comes into focus.','A glass-and-steel redesign introduced the Retina display. A front-facing camera and FaceTime made seeing the person on the other end part of the experience.',['Retina display','FaceTime','Glass & steel'],'3.5 inches','Apple A4','June 24, 2010','https://www.apple.com/newsroom/2010/06/07Apple-Presents-iPhone-4/'],
[2011,'iPhone 4s','Just ask.','Siri introduced a conversational way to use your phone. The A5 chip, an 8-megapixel camera, and 1080p video recording refined the experience inside the familiar glass design.',['Siri','8 MP camera','iCloud'],'3.5 inches','Apple A5','October 14, 2011','https://www.apple.com/newsroom/2011/10/04Apple-Launches-iPhone-4S-iOS-5-iCloud/'],
[2012,'iPhone 5','A little taller. A lot lighter.','The display grew to four inches in a thinner aluminum body. LTE brought faster mobile data, while the compact Lightning connector replaced the 30-pin dock connection.',['LTE','Lightning','Aluminum body'],'4 inches','Apple A6','September 21, 2012',modelGuide],
[2013,'iPhone 5s','A more personal touch.','Touch ID brought fingerprint authentication to the Home button. The A7 introduced 64-bit architecture, while the colorful iPhone 5c offered another expression of the iPhone.',['Touch ID','64-bit A7','True Tone flash'],'4 inches','Apple A7','September 20, 2013','https://www.apple.com/newsroom/2013/09/10Apple-Announces-iPhone-5s-The-Most-Forward-Thinking-Smartphone-in-the-World/'],
[2014,'iPhone 6','A bigger canvas.','Rounded edges and a larger display gave iPhone a new silhouette. The 6 Plus offered an even bigger option, and Apple Pay introduced a new way to make contactless purchases.',['Larger displays','Apple Pay','Rounded design'],'4.7 inches','Apple A8','September 19, 2014',modelGuide],
[2015,'iPhone 6s','Another dimension of touch.','3D Touch added pressure-sensitive interactions. Live Photos captured a moment around each photograph, and a 12-megapixel camera brought 4K video recording to iPhone.',['3D Touch','Live Photos','4K video'],'4.7 inches','Apple A9','September 25, 2015',modelGuide],
[2016,'iPhone 7','Ready for the unexpected.','Water resistance and stereo speakers expanded what iPhone could do. The Home button became solid-state, while iPhone 7 Plus introduced a dual-camera system and Portrait mode.',['Water resistance','Stereo speakers','Solid-state Home'],'4.7 inches','Apple A10 Fusion','September 16, 2016',modelGuide],
[2017,'iPhone X','The screen takes over.','Ten years after the original, iPhone X traded the Home button for gestures. Its OLED display, TrueDepth camera, and Face ID reimagined how people looked at—and unlocked—their phone. iPhone 8 also debuted that year.',['Face ID','OLED display','Wireless charging'],'5.8 inches','Apple A11 Bionic','November 3, 2017','https://www.apple.com/newsroom/2017/09/the-future-is-here-iphone-x/'],
[2018,'iPhone XS','The idea, expanded.','iPhone XS refined the all-screen design with the A12 Bionic chip and Smart HDR. XS Max brought it to a larger display, while iPhone XR offered a colorful LCD alternative.',['Smart HDR','A12 Bionic','Dual SIM'],'5.8 inches','Apple A12 Bionic','September 21, 2018',modelGuide],
[2019,'iPhone 11','A wider view of the world.','An Ultra Wide camera opened up new perspectives, while Night mode improved low-light photographs. The iPhone 11 Pro family introduced a three-camera system.',['Ultra Wide camera','Night mode','A13 Bionic'],'6.1 inches','Apple A13 Bionic','September 20, 2019',modelGuide],
[2020,'iPhone 12','A new era of connection.','5G arrived alongside flat edges, OLED across the main lineup, and Ceramic Shield. MagSafe introduced a magnetic system for charging and accessories, with a compact mini joining the family.',['5G','MagSafe','Ceramic Shield'],'6.1 inches','Apple A14 Bionic','October 23, 2020','https://www.apple.com/newsroom/2020/10/apple-announces-iphone-12-and-iphone-12-mini-a-new-era-for-iphone-with-5g/'],
[2021,'iPhone 13','The story gets cinematic.','Cinematic mode brought shifting focus to video. Improved battery life and sensor-shift stabilization refined the everyday model, while the Pro family introduced ProMotion displays.',['Cinematic mode','Sensor-shift OIS','A15 Bionic'],'6.1 inches','Apple A15 Bionic','September 24, 2021',modelGuide],
[2022,'iPhone 14 Pro','An island of possibility.','Dynamic Island transformed the camera cutout into an interface for live activities. A 48-megapixel main camera and Always-On display arrived on the Pro family, alongside the iPhone 14 and 14 Plus.',['Dynamic Island','48 MP main camera','Always-On display'],'6.1 inches','Apple A16 Bionic','September 16, 2022',modelGuide],
[2023,'iPhone 15','A more universal connection.','USB-C replaced Lightning, and Dynamic Island reached the standard models. A 48-megapixel main camera expanded photographic options; the Pro family added titanium and the Action button.',['USB-C','Dynamic Island','48 MP main camera'],'6.1 inches','Apple A16 Bionic','September 22, 2023','https://www.apple.com/newsroom/2023/09/apple-debuts-iphone-15-and-iphone-15-plus/'],
[2024,'iPhone 16','Camera, at your fingertips.','Camera Control offered a dedicated way to access photo and video tools. The Action button reached the standard lineup, and the A18 chip supported Apple Intelligence features as they rolled out.',['Camera Control','Action button','A18 chip'],'6.1 inches','Apple A18','September 20, 2024',modelGuide],
[2025,'iPhone 17','A smoother everyday.','ProMotion arrived on the standard iPhone 17, alongside a larger display and an 18-megapixel Center Stage front camera. The year also brought iPhone Air, a new thin titanium design.',['ProMotion','Center Stage camera','A19 chip'],'6.3 inches','Apple A19','September 19, 2025','https://www.apple.com/newsroom/2025/09/apple-debuts-iphone-17/']
].map(([year,name,headline,description,features,display,chip,release,source])=>({year,name,headline,description,features,display,chip,release,source}));
let selected=2007, era='all';
const $=id=>document.getElementById(id);
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filtered(){return records.filter(r=>era==='all'||(era==='early'&&r.year<=2012)||(era==='growth'&&r.year>=2013&&r.year<=2018)||(era==='modern'&&r.year>=2019));}
function renderYears(){const list=filtered();$('item-count').textContent=`${list.length} chapters`;$('year-scroll').innerHTML=list.map(r=>`<button data-year="${r.year}" class="${r.year===selected?'selected':''}" aria-pressed="${r.year===selected}">${r.year}</button>`).join('');}
function renderExhibit(){const r=records.find(r=>r.year===selected);const index=records.indexOf(r);$('exhibit-number').textContent=`${String(index+1).padStart(2,'0')} / 19`;$('background-year').textContent=r.year;$('exhibit-era').textContent=`${r.year<=2012?'THE PIONEERS':r.year<=2018?'THE EXPANSION':'THE NEW ERA'} / ${r.year}`;$('model-name').textContent=r.name;$('model-headline').textContent=r.headline;$('model-description').textContent=r.description;$('feature-tags').innerHTML=r.features.map(f=>`<span>${escapeHTML(f)}</span>`).join('');$('specs').innerHTML=[['Display',r.display],['Chip',r.chip],['Released',r.release]].map(([label,value])=>`<div><dt>${label}</dt><dd>${escapeHTML(value)}</dd></div>`).join('');$('source-link').href=r.source;$('source-link').textContent=r.source===modelGuide?'Explore Apple’s model archive ↗':'Explore the original announcement ↗';const image=document.createElement('img');image.src=imageBase+productImages[r.year];image.alt=`${r.name}: official Apple product image showing available finishes and device views`;image.className='exhibit-product-photo';image.decoding='async';image.addEventListener('error',()=>{if(selected!==r.year)return;const fallback=document.createElement('a');fallback.href=modelGuide;fallback.target='_blank';fallback.rel='noopener';fallback.className='photo-unavailable';fallback.textContent=`View ${r.name} photos on Apple’s archive ↗`;$('exhibit-phone').replaceChildren(fallback);});$('exhibit-phone').replaceChildren(image);renderGallery();const list=filtered();const position=list.findIndex(r=>r.year===selected);$('previous').disabled=position===0;$('next').disabled=position===list.length-1;renderYears();}
function selectYear(year){selected=Number(year);renderExhibit();}
document.querySelectorAll('[data-era]').forEach(button=>button.addEventListener('click',()=>{era=button.dataset.era;document.querySelectorAll('[data-era]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});if(!filtered().some(r=>r.year===selected))selected=filtered()[0].year;renderExhibit();}));
$('year-scroll').addEventListener('click',event=>{const button=event.target.closest('[data-year]');if(button)selectYear(button.dataset.year);});
function step(direction){const list=filtered();const next=list[list.findIndex(r=>r.year===selected)+direction];if(next){selectYear(next.year);document.querySelector('.year-scroll .selected').scrollIntoView({block:'nearest',inline:'nearest'});}}
$('previous').addEventListener('click',()=>step(-1));$('next').addEventListener('click',()=>step(1));
$('year-scroll').addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();step(event.key==='ArrowRight'?1:-1);document.querySelector('.year-scroll .selected').focus();}});
document.querySelectorAll('.moment').forEach(button=>button.addEventListener('click',()=>{era='all';document.querySelectorAll('[data-era]').forEach(b=>{b.classList.toggle('active',b.dataset.era==='all');b.setAttribute('aria-pressed',String(b.dataset.era==='all'));});selectYear(button.dataset.year);$('timeline').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
for(const id of ['compare-a','compare-b']){$(id).innerHTML=records.map(r=>`<option value="${r.year}">${r.year} · ${escapeHTML(r.name)}</option>`).join('');$(id).addEventListener('change',renderComparison);}
$('compare-a').value='2007';$('compare-b').value='2025';
function renderComparison(){const a=records.find(r=>r.year===Number($('compare-a').value));const b=records.find(r=>r.year===Number($('compare-b').value));$('comparison').innerHTML=[['Model',a.name,b.name],['Released',a.release,b.release],['Display',a.display,b.display],['Chip',a.chip,b.chip],['Key features',a.features.join(' · '),b.features.join(' · ')],['The idea',a.headline,b.headline]].map(row=>`<div class="comparison-row">${row.map(value=>`<span>${escapeHTML(value)}</span>`).join('')}</div>`).join('');}
$('compare-open').addEventListener('click',()=>{renderComparison();$('compare-dialog').showModal();});$('compare-close').addEventListener('click',()=>$('compare-dialog').close());$('compare-dialog').addEventListener('click',event=>{if(event.target===$('compare-dialog')){const rect=$('compare-dialog').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('compare-dialog').close();}});


function renderGallery(){
$('photo-gallery').innerHTML=filtered().map(r=>`<button class="photo-card ${r.year===selected?'selected':''}" data-photo-year="${r.year}" aria-pressed="${r.year===selected}"><img src="${imageBase+productImages[r.year]}" alt="Apple product image of ${escapeHTML(r.name)}" loading="lazy" decoding="async"><span><b>${escapeHTML(r.name)}</b><small>${r.year}</small></span></button>`).join('');
}
$('photo-gallery').addEventListener('click',event=>{const card=event.target.closest('[data-photo-year]');if(card){selectYear(card.dataset.photoYear);$('exhibit').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}});
let activeVideoYear=2007;
function renderVideo(year){
const video=launchVideos.find(v=>v.year===year);if(!video)return;activeVideoYear=year;
$('video-stage').innerHTML=`<button class="video-poster" id="video-play" aria-label="Play ${escapeHTML(video.title)}"><img src="https://i.ytimg.com/vi/${video.id}/hqdefault.jpg" alt="${escapeHTML(video.title)} launch event thumbnail" loading="lazy"><span class="play-circle">▶</span><span class="poster-label">${video.year} / WATCH THE ORIGINAL EVENT</span></button>`;
$('video-credit').textContent=video.credit;$('video-title').textContent=video.title;$('video-description').textContent=video.description;$('video-external').href=`https://www.youtube.com/watch?v=${video.id}${video.start?'&t='+video.start+'s':''}`;
$('launch-playlist').innerHTML=launchVideos.map(v=>`<button class="launch-choice ${v.year===year?'active':''}" data-video-year="${v.year}" aria-pressed="${v.year===year}"><img src="https://i.ytimg.com/vi/${v.id}/default.jpg" alt="" loading="lazy"><span><small>${v.date}</small><b>${escapeHTML(v.title)}</b><em>${escapeHTML(v.credit)}</em></span><span class="playlist-play">▶</span></button>`).join('');
$('video-play').addEventListener('click',()=>{const iframe=document.createElement('iframe');iframe.src=`https://www.youtube-nocookie.com/embed/${video.id}?autoplay=1&rel=0${video.start?'&start='+video.start:''}`;iframe.title=video.title;iframe.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';$('video-stage').replaceChildren(iframe);});
}
$('launch-playlist').addEventListener('click',event=>{const button=event.target.closest('[data-video-year]');if(button)renderVideo(Number(button.dataset.videoYear));});

renderExhibit();renderComparison();renderVideo(2007);
